# ============================================================ Week 5
_ov5 = (h2('本节定位')
 + p('上一讲把文字变成了字节。这一讲把「看得见的东西」变成字节：一张照片在内存里到底是什么？答案是三层——先采样（在哪取点）、再量化（每点取什么值）、最后编码（值怎么写位）。这三步与上一讲的「字符 → 码位 → 字节」是同一套思路，只是把「符号」换成了「亮度」。')
 + p('本讲还要算清一件事：图像到底占多少空间。公式只有一条 <code>W × H × B / 8</code>（宽 × 高 × 每像素位数 ÷ 8），但它是后面所有多媒体计算题的母公式——第 6 讲的音频、视频，第 7 讲的压缩比，都从这条公式出发。')
 + p('最后一块内容是栅格与矢量的分工：照片用栅格，logo 用矢量。这不是审美偏好，而是「信息本质不同」导致的必然选择：连续色调适合采样成像素，几何形状适合写成数学描述。')
 + p('学完本讲你应当能够：')
 + ck('用「采样—量化—编码」三步说明任何图像怎样变成数字',
      '区分采样（离散化位置）与量化（离散化取值）',
      '计算分辨率给出的总像素数，并换算成百万像素（MP）',
      '说明 8 位灰度为什么有 256 级、24 位 RGB 为什么有约 1 677 万色',
      '用 <code>W × H × B / 8</code> 计算未压缩图像的字节数并换算单位',
      '说明栅格与矢量的差别，并针对具体任务选择合适的一种',
      '解释「色深」这个词在不同表示下含义为何不同'))

_d5a = (h2('一、从连续到离散：数字化的三步')
 + p('课件开篇先立一个前提：现实世界的图像本来不是数字的。现实世界是<b>连续的</b>视觉信息，而计算机需要<b>离散</b>的数值数据。把连续信息转成离散数字数据的过程叫<b>数字化</b>（digitization）。')
 + p('数字化的流水线固定为三步：')
 + pre('现实场景 → 采样（Sampling）→ 量化（Quantization）→ 编码（Encoding）→ 二进制数据')
 + p('这三步各回答一个问题，课件在第 20 页把它们并列得非常清楚：')
 + tb(('步骤', '回答的问题', '输出'),
      ('采样 Sampling', '在哪里测量？（Where?）', '像素网格'),
      ('量化 Quantization', '给它什么值？（What value?）', '有限的数值集合'),
      ('编码 Encoding', '怎样用位表示？（How in bits?）', '二进制数据'))
 + p('记住这三问，后面讲音频与视频时你会发现它们一字不改地复用（第 6 讲：采样 = when、量化 = what value、编码 = how）。')
 + h2('二、数字图像与像素')
 + h3('2.1 数字图像的定义')
 + p('课件定义：数字图像是视觉信息的<b>数值表示</b>。它由许多像素组成，每个像素带有数值信息，这些数值可以用位来表示：')
 + pre('图像 → 像素 → 数值 → 二进制数据')
 + h3('2.2 像素')
 + p('像素（pixel）= picture element（图像元素）。课件说它是<b>栅格图像的基本元素</b>：每个小方格代表一个像素，图像就是像素的二维排布，每个像素存一份数值信息。')
 + h3('2.3 把图像看成一个二维矩阵')
 + p('灰度图像可以直接写成矩阵。课件给了记号 <code>I(x, y)</code>：x 是水平位置，y 是垂直位置，<code>I(x, y)</code> 是该位置的像素值。')
 + pre('100  120  135  150\n 80   95  110  125\n 50   70   90  105')
 + p('这个视角很重要：一旦图像变成矩阵，所有矩阵运算都能用在图像上（求平均做模糊、求差分做边缘检测、做直方图统计分布）。第 7 讲压缩时「相邻像素高度相关」这句话，指的就是矩阵里相邻元素数值接近。')
 + h2('三、采样：决定在哪里取点')
 + h3('3.1 定义')
 + p('采样从连续信息中选取<b>离散位置</b>。它回答「在哪里测量」：把连续的空间信息变成离散的像素位置。')
 + pre('连续图像 → 在离散位置测量 → 像素网格')
 + h3('3.2 一个直观的想象')
 + p('把连续图像想成一整片颜色连续变化的区域，采样就是在上面盖一张网格，网格的每个交叉点成为一个像素位置。课件特别提醒一句：<b>每个像素记录的颜色/亮度值仍然是连续的</b>——采样只解决了「位置」，没解决「取值」。取值留给量化。')
 + h3('3.3 采样与空间分辨率')
 + p('采样点的数量决定<b>空间分辨率</b>（spatial resolution）：采样点越多，能表示的细节越多。课件用两组疏密不同的点阵对比：')
 + pre('低采样：      •       •       •\n              •       •       •\n\n高采样：  • • • • • • • •\n          • • • • • • • •')
 + h3('3.4 分辨率怎么写')
 + p('图像分辨率用像素数描述。课件给了四个常见值：')
 + tb(('分辨率', '含义', '常见场景'),
      ('640 × 480', '横向 640、纵向 480', '早期视频、低清'),
      ('1280 × 720', '720p', '标清视频'),
      ('1920 × 1080', '1080p（全高清）', '主流视频、显示器'),
      ('3840 × 2160', '4K UHD', '高清视频、专业显示'))
 + p('注意写法是「宽 × 高」，不是「高 × 宽」。顺序反了不影响总像素数，但影响你对画面比例的判断。')
 + h3('3.5 总像素数与百万像素')
 + p('公式：')
 + p('<b><code>像素总数 = 宽 × 高</code></b>')
 + pre('1920 × 1080 = 2 073 600')
 + p('约 207 万像素，通常写作 <b>2.07 MP</b>（megapixel）。手机相机标称的「4800 万像素」，说的就是这个乘积。')
 + h3('3.6 分辨率高不等于画质好')
 + p('课件特意加了一句反直觉的提醒：更高分辨率通常能表示更多空间细节，但<b>高分辨率并不自动等于更好的画质</b>。画质还取决于：')
 + chips(['镜头 lens', '传感器 sensor', '光照 lighting', '噪点 noise', '颜色表示 color representation', '图像处理 image processing'])
 + p('这句话在考试里常以「为什么 4800 万像素的手机照片不如 2400 万像素的单反」出现。答案是：像素数只是采样密度，量化精度、镜头解析力、噪声水平都会限制最终画质。')
 + h2('四、量化：决定每点多亮')
 + h3('4.1 定义')
 + p('采样之后，每个像素仍然是一个连续量（例如某个亮度）。量化把连续值映射到<b>有限的离散值集合</b>。它回答「给它什么值」。')
 + pre('连续亮度 → 量化 → 离散数值')
 + h3('4.2 与采样的对照')
 + tb(('过程', '主要问题', '例子'),
      ('采样 Sampling', '在哪里测量？', '像素网格'),
      ('量化 Quantization', '给它什么值？', '亮度 0–255'))
 + p('一句话：<b>采样离散化位置，量化离散化取值</b>。这两个词在学生作业里最常被混，记住这句就不会错。')
 + h3('4.3 量化的样子')
 + p('假设亮度是 0 到 1 的连续量，量化把它切成有限档：')
 + pre('0 ─────────────────────── 1\n0   1   2   3   4   5   6   7')
 + p('本来有无穷多个可能值，现在只用 8 个。档数越多，越接近原始连续值；档数越少，越容易出现「色带」（banding）。')
 + h3('4.4 灰度约定')
 + p('灰度图像表示亮度。课件给的约定是：<code>0 → 黑</code>、<code>255 → 白</code>，中间是各种灰。')
 + pre('0        64       128       192       255\n黑                                白')
 + h3('4.5 8 位灰度')
 + p('8 位像素有 <code>2^8 = 256</code> 种可能值，于是：')
 + p('<b>8 位灰度 → 256 个灰度级，范围 0–255</b>')
 + p('这个数字与第 4 讲的 ASCII（128 个字符）形成对照：位宽决定容量，7 位给 128、8 位给 256。')
 + h3('4.6 灰度图就是一张数字表')
 + p('课件给了第二个矩阵例子：')
 + pre(' 20   50   80\n100  130  160\n180  210  240')
 + p('所以「灰度图像本质上是一个二维数字数组」。这句话把图像处理与数组处理接上了：一张 8 位灰度图，就是 <code>height × width</code> 个 0–255 的整数。')
 + h2('五、编码：把值写成位')
 + p('量化之后我们有一堆离散数值。编码规定这些值怎样表示成数字数据。它回答「怎样用位表示」。')
 + pre('量化值 → 编码 → 二进制数据')
 + p('课件给了一个最简单的例子：某像素值是 128，用 8 位二进制编码就是 <code>10000000</code>。')
 + p('这个概念与上一讲的 ASCII 完全对应：一个是「字符 → 编号 → 字节」，一个是「亮度值 → 8 位二进制」。都是把有限集合里的元素映射到固定长度的位串。'))

_d5b = (h2('六、彩色图像与 RGB')
 + h3('6.1 RGB 模型')
 + p('课件问：计算机怎样表示颜色？常见方法是 RGB 彩色模型，RGB 分别是 Red、Green、Blue。一个颜色像素写成三元组 <code>(R, G, B)</code>。')
 + p('为什么是这三种颜色？因为人眼视网膜有三类视锥细胞，分别对长、中、短波敏感。用三原色按比例叠加，就能「骗过」视觉系统产生任意颜色的感觉。这是感知层面的设计依据，不是物理上的唯一方案。')
 + h3('6.2 关键颜色表')
 + tb(('颜色', 'R', 'G', 'B'),
      ('黑 Black', '0', '0', '0'),
      ('红 Red', '255', '0', '0'),
      ('绿 Green', '0', '255', '0'),
      ('蓝 Blue', '0', '0', '255'),
      ('白 White', '255', '255', '255'))
 + p('这张表有两个可推的规律：三通道全 0 是黑，全满（255）是白；只点亮一个通道得纯色。所以「灰度」在三通道里是 R = G = B 的情形。')
 + h3('6.3 24 位 RGB')
 + p('常见表示给每个通道 8 位：')
 + pre('8（R）+ 8（G）+ 8（B）= 24 位/像素 = 3 字节/像素')
 + h3('6.4 一共多少种颜色')
 + p('每个通道有 <code>2^8 = 256</code> 种取值，三个通道组合：')
 + p('<b><code>256 × 256 × 256 = 256^3 = 16 777 216</code></b>')
 + p('约 1677 万色，这就是常说的「真彩色」（true color）。课件写作 approximately 16.7 million colors。')
 + h3('6.5 一个像素的二进制样子')
 + p('课件取 <code>RGB = (255, 128, 0)</code>：')
 + pre('R = 255 → 11111111\nG = 128 → 10000000\nB =   0 → 00000000\n拼起来：11111111 10000000 00000000')
 + p('共 24 位 = 3 字节。这个颜色是橙色（红满、绿半、蓝无）。写十六进制就是 <code>FF8000</code>，网页 CSS 里常写成 <code>#ff8000</code>——这正是第 4 讲「十六进制是二进制的压缩写法」的实际用途。')
 + h2('七、色深（color depth）')
 + h3('7.1 定义')
 + p('色深描述用多少位来表示像素信息。有了 n 位，可能取值数是 <code>2^n</code>：')
 + tb(('色深', '可能取值数', '典型含义'),
      ('1 位', '2', '黑白二值（只有黑与白）'),
      ('2 位', '4', '4 级灰度或 4 色'),
      ('4 位', '16', '16 色'),
      ('8 位', '256', '256 级灰度，或 256 色调色板'),
      ('24 位', '约 1677 万', 'RGB 真彩色（8+8+8）'))
 + h3('7.2 「8 位」的含义取决于分配方式')
 + p('这是本讲最容易答错的一个概念。课件专门提醒：<b>「8 位」的意思取决于位怎样分配</b>。')
 + tb(('说法', '位怎么分', '结果'),
      ('8 位灰度', '8 位全给亮度', '256 级灰'),
      ('24 位 RGB', '8 位 × 3 个通道', '约 1677 万色'),
      ('8 位索引色', '8 位作调色板下标', '从一张调色板里挑 256 种颜色'))
 + p('所以答题时要先问「这些位怎么分」。只说「8 位」而不说分配方式，是不完整的答案。')
 + h2('八、图像占多少数据')
 + h3('8.1 公式')
 + p('对未压缩的栅格图像：')
 + p('<b><code>大小（位）= W × H × B</code></b>，其中 W 是宽、H 是高、B 是每像素位数。')
 + p('<b><code>大小（字节）= W × H × B / 8</code></b>')
 + h3('8.2 算例一：1024 × 768 的 8 位灰度图')
 + pre('像素数：1024 × 768 = 786 432\n每像素：8 位 = 1 字节\n总字节：786 432 字节 ≈ 768 KiB')
 + p('注意 <code>786 432 / 1024 = 768</code>，正好 768 KiB——因为 1024 × 768 本身就是 2 的幂的乘积，除以 1024 后干净整除。这类题常故意选这种尺寸，算起来快。')
 + h3('8.3 算例二：1920 × 1080 的 24 位 RGB 图')
 + pre('像素数：1920 × 1080 = 2 073 600\n每像素字节：24 / 8 = 3\n总字节：2 073 600 × 3 = 6 220 800 字节\n换算：6 220 800 / (1024 × 1024) ≈ 5.93 MiB')
 + p('课件两次都加了一句提醒：<b>这是未压缩的原始像素数据</b>。真实文件通常更小，因为有压缩（第 7 讲）；也可能更大，因为有元数据与文件头。')
 + h3('8.4 什么在决定数据量')
 + p('课件给的比例关系：<b>数据量 ∝ 分辨率 × 色深</b>。因此数据量会在三种情况下增大：分辨率升高、每像素位数升高、通道数增多。')
 + cal('tip', '单位别混', '<code>MiB = 1024 × 1024</code> 字节，<code>MB = 10^6</code> 字节。5.93 MiB 换成十进制 MB 是 6.22 MB，差 5%。第 4 章与第 6 章会反复用到这个差别，答题时看清题目给的是哪种单位。')
 + h2('九、栅格图像（raster）')
 + h3('9.1 定义与例子')
 + p('栅格图像用像素网格表示图像：<code>图像 → 像素网格 → 像素值 → 二进制数据</code>。典型例子：照片、屏幕截图、扫描文档、数字绘画。')
 + h3('9.2 分辨率依赖与像素化')
 + p('栅格图像是<b>分辨率相关</b>的。放大到一定程度，单个像素变得可见，这种现象叫<b>像素化</b>（pixelation）。原因很直接：图像里只有那么多像素，放大只是把每个像素铺得更开，不会产生新细节。')
 + h3('9.3 优点与局限')
 + tb(('优点', '局限'),
      ('适合照片', '分辨率相关'),
      ('能表示复杂颜色', '放大会像素化'),
      ('能表示细腻纹理', '高分辨率图像占大量存储'),
      ('保留像素级信息', '—'))
 + h2('十、矢量图形（vector）')
 + h3('10.1 定义')
 + p('矢量图像用<b>对象的数学描述</b>表示视觉信息。基本元素是点、线、曲线、圆、多边形。')
 + p('课件的例子：一个圆由「圆心 (100, 100)、半径 50、颜色红」描述。图形由对象描述，而不是由一个个像素描述。')
 + h3('10.2 栅格与矢量对照')
 + tb(('对照项', '栅格 Raster', '矢量 Vector'),
      ('基本单位', '像素', '几何对象'),
      ('表示方式', '像素值', '数学描述'),
      ('分辨率相关', '是', '一般不是'),
      ('照片', '适合', '通常不适合'),
      ('logo / 图标', '可用', '常用'),
      ('缩放', '可能像素化', '可平滑缩放'))
 + p('课件加了一句关键说明：矢量图形之所以能平滑缩放，是因为它可以按需<b>重新计算</b>——放大两倍就是把半径改成 100 再画一遍，而不是把已有的点铺开。')
 + h3('10.3 什么时候用哪种')
 + tb(('适合栅格', '适合矢量'),
      ('照片', 'logo'),
      ('真实场景', '图标'),
      ('复杂纹理', '示意图（diagrams）'),
      ('屏幕截图', '图表（charts）'),
      ('扫描图像', '简单插画'))
 + p('课件的结论是：<b>合适的表示取决于视觉信息的类型</b>。判据只有一条——信息本身是「连续色调」还是「几何形状」。')
 + h3('10.4 常见格式')
 + tb(('栅格格式', '矢量格式'),
      ('JPEG / JPG、PNG、GIF、BMP、TIFF', 'SVG、EPS'))
 + p('课件补了一句：某些格式（如 PDF）既能含矢量图形，也能含其他内容。并强调：<b>文件格式规定图像数据怎样组织与存储</b>——格式与「表示方式」是两件事。')
 + h2('十一、完整流水线与三个概念的分工')
 + pre('现实场景 → 采样 → 量化 → 编码 → 二进制数据\n（像素网格） （像素值） （位）')
 + p('课件在最后一页把三个容易混的概念并列：')
 + tb(('概念', '问的问题', '例子'),
      ('表示（representation）', '视觉信息怎样被表示？', '像素、RGB、灰度、矢量对象'),
      ('编码（encoding）', '这些值怎样数字化？', '128 → 10000000'),
      ('压缩（compression）', '怎样减少数据量？', '大数据 → 压缩 → 小数据'))
 + p('这三层要分清：表示决定「用什么模型」，编码决定「怎么写位」，压缩决定「能不能更省」。第 7 讲整讲都在第三层。')
 + h2('十二、课件小测（附答案）')
 + ol('分辨率 800 × 600 的图像有多少像素？→ <code>800 × 600 = 480 000</code> 像素',
      '8 位灰度的可能亮度级数？→ <code>2^8 = 256</code> 级，范围 0–255',
      '800 × 600、8 位的灰度图需要多少原始数据？→ <code>800 × 600 × 8 / 8 = 480 000</code> 字节',
      '照片 / 公司 logo / 截图 / 数学示意图分别用哪种？→ 栅格 / 矢量 / 栅格 / 矢量'))

_kw5 = K(('digitization', '数字化', 'Converting continuous real-world information into discrete digital data.'),
         ('sampling', '采样', 'Selecting discrete positions; answers "where do we measure?".'),
         ('quantization', '量化', 'Mapping continuous values onto a finite set of discrete values; answers "what value?".'),
         ('encoding', '编码', 'Representing quantized values as bits, e.g. 128 → 10000000.'),
         ('pixel', '像素', 'Picture element, the basic unit of a raster image.'),
         ('spatial resolution', '空间分辨率', 'The number of sampling points, written width × height.'),
         ('megapixel', '百万像素', 'One million pixels; 1920 × 1080 ≈ 2.07 MP.'),
         ('grayscale', '灰度', 'Brightness only; 8-bit grayscale gives 256 levels from 0 (black) to 255 (white).'),
         ('RGB', '红绿蓝模型', 'A colour written as (R, G, B); 24-bit RGB uses 8 bits per channel.'),
         ('colour depth', '色深', 'Number of bits per pixel; 2^n possible values.'),
         ('raster image', '栅格图像', 'An image stored as a grid of pixels; resolution dependent.'),
         ('pixelation', '像素化', 'Visible individual pixels when a raster image is enlarged.'),
         ('vector graphic', '矢量图形', 'An image described by mathematical objects such as points, lines and curves.'),
         ('resolution dependent', '分辨率相关', 'Detail is fixed at creation time and cannot be recovered by zooming.'),
         ('uncompressed size', '未压缩数据量', 'W × H × B / 8 bytes for a raster image.'))

_ex5 = (qa('例 1　算 800 × 600、8 位灰度图的未压缩数据量，再算同一尺寸 24 位 RGB 的数据量。',
    p('<b>8 位灰度：</b><code>800 × 600 = 480 000</code> 像素，每像素 1 字节 → <b>480 000 字节</b>。')
    + p('换算：<code>480 000 / 1024 ≈ 468.75 KiB</code>；换成十进制是 <code>480 kB</code>。')
    + p('<b>24 位 RGB：</b>每像素 3 字节 → <code>480 000 × 3 = 1 440 000</code> 字节 ≈ <b>1.37 MiB</b>。')
    + p('比值正好 3 倍。这说明「同样的画面，彩色比灰度多 3 倍数据」——因为通道数从 1 变 3。凡是「彩色图是灰度图的几倍」的题，答案都是通道数之比。')
    + p('答题时务必写清「未压缩」，否则严格说不成立：压缩后的文件可能小得多（第 7 讲）。'))
  + qa('例 2　一张 4000 × 3000、24 位色的照片，未压缩时是多少 MB？（按 1 MB = 10^6 字节）',
    p('<b>第一步，算像素数：</b><code>4000 × 3000 = 12 000 000</code> 像素，即 1200 万像素。')
    + p('<b>第二步，算每像素字节：</b><code>24 / 8 = 3</code> 字节。')
    + p('<b>第三步，相乘：</b><code>12 000 000 × 3 = 36 000 000</code> 字节。')
    + p('<b>第四步，换算：</b><code>36 000 000 / 10^6 =</code> <b>36 MB</b>。')
    + p('这道题与 Exercise 3 第 6 题同型。注意题目若给「1 MB = 10^6 字节」，就不要用 1024 去除；若给 MiB，则用 <code>1024 × 1024</code>。单位口径错了，答案会差 4.8%。')
    + p('补充判断：真实 JPEG 通常只有几 MB，说明压缩率可达十倍以上——这正是第 7 讲「有损压缩能大幅缩小」的证据。'))
  + qa('例 3　一个像素 RGB = (255, 128, 0)，写出它的二进制、十六进制与字节数，并说明它是什么颜色。',
    p('三个通道分别转 8 位二进制：<code>255 = 1111 1111</code>、<code>128 = 1000 0000</code>、<code>0 = 0000 0000</code>。')
    + p('拼接：<code>11111111 10000000 00000000</code>，共 24 位 = <b>3 字节</b>。')
    + p('按 4 位一组转十六进制：<code>1111 1111 | 1000 0000 | 0000 0000</code> → <code>FF | 80 | 00</code> → <b>0xFF8000</b>。')
    + p('颜色判断：红满（255）、绿半（128）、蓝无（0）→ 橙色。红 + 半绿 = 橙，这是 RGB 混色的直观推论。')
    + p('注意通道顺序是 R、G、B。若顺序写成 BGR（某些图像库的默认），同样的颜色会变成 <code>0080FF</code>，颜色完全变了——这是编程里极常见的 bug 来源。'))
  + qa('例 4　判断下列任务该用栅格还是矢量，并说明判据：照片、公司 logo、屏幕截图、数学示意图、地图图标。',
    p('<b>照片 → 栅格。</b>照片是连续色调，含大量细微的颜色渐变与纹理，只能用采样量化表示；用矢量描述反而无法表达。')
    + p('<b>公司 logo → 矢量。</b>logo 由几何形状与文字构成，需要在名片、招牌、屏幕上任意缩放而不失真。')
    + p('<b>屏幕截图 → 栅格。</b>截图本身就是像素数据（连字体渲染的抗锯齿边缘也是像素），没有可还原的几何描述。')
    + p('<b>数学示意图 → 矢量。</b>由直线、圆、曲线、标注组成，缩放后要保持清晰，且便于修改某个元素。')
    + p('<b>地图图标 → 矢量。</b>要在不同缩放级别与不同屏幕上保持锐利，且可换配色。')
    + p('通用判据两步：① 信息是连续色调还是几何形状？② 是否需要任意缩放？两步都指向「形状 + 缩放」就选矢量。')))

_pr5 = (ol('算 640 × 480、8 位灰度图的未压缩字节数与 KiB。',
          '2 位与 4 位的色深分别有多少种取值？若 4 位全部给亮度，灰度可分几级？',
          '算 1920 × 1080、24 位 RGB 图换成 MiB 是多少。',
          '为什么「高分辨率不自动等于高画质」？至少给三个其他因素。',
          '矢量图放大为什么不会失真？请从「表示方式」的角度解释。',
          '一张 1000 × 1000、24 位的图未压缩是 3 MB，但存成 JPEG 只有 200 KB。这个差别可能吗？依据是什么？')
 + det('参考答案与思路',
    p('<b>1.</b> <code>640 × 480 = 307 200</code> 像素，每像素 1 字节 → <b>307 200 字节</b>；<code>307 200 / 1024 = 300 KiB</code>。')
    + p('<b>2.</b> <code>2^2 = 4</code> 种；<code>2^4 = 16</code> 种。若 4 位全给亮度，灰度可分 16 级（0–15）。级数少时会出现明显色带。')
    + p('<b>3.</b> <code>1920 × 1080 = 2 073 600</code> 像素 × 3 字节 = <code>6 220 800</code> 字节；<code>/ 1 048 576 ≈ 5.93 MiB</code>。')
    + p('<b>4.</b> 分辨率只决定采样密度。其他因素：镜头解析力（模糊的光学系统采样再密也没细节）、传感器噪声（高 ISO 的噪点会盖住细节）、光照与动态范围（过曝处全是 255）、色彩量化精度（位数少则有色带）、后端处理（锐化/降噪会改细节）。')
    + p('<b>5.</b> 矢量图存的不是像素而是「圆心、半径、颜色」这类描述，放大时按新尺寸<b>重新计算并绘制</b>，所以边缘依旧锐利；栅格图存的是固定数量的像素值，放大只是把已有像素拉伸，因此出现像素化。')
    + p('<b>6.</b> 可能。原因有两点：① 未压缩的 3 MB 是「原始像素数据」；② JPEG 是有损压缩，利用了相邻像素高度相关（空间冗余）并丢弃人眼不敏感的高频细节（第 7 讲）。1000 × 1000 × 3 = 3 000 000 字节 = 3 MB（十进制），压缩到 200 KB 意味着约 15:1 的压缩比，对照片是常见的。')))

_exam5 = (cal('exam', '必考', '① 采样与量化的区别（位置 vs 取值）；② <code>W × H × B / 8</code> 的计算与单位换算；③ 8 位灰度 256 级、24 位 RGB 约 1 677 万色；④ RGB 三元组与十六进制写法；⑤ 栅格与矢量的选择判据；⑥ 分辨率的写法与总像素数。')
 + cal('warn', '易错 1', '把采样与量化说反。记法：「采样 = 采点（位置）」「量化 = 定值（取值）」。')
 + cal('warn', '易错 2', '算大小忘记除以 8。公式给的是「位」，问的是「字节」，差 8 倍。')
 + cal('warn', '易错 3', '把 MB 与 MiB 混用。题目给了「1 MB = 10^6 字节」就按十进制，别用 1024。')
 + cal('warn', '易错 4', '以为「8 位」总是 256 级灰度。8 位也可能是指数色（调色板下标）或某个通道的位宽，要看位怎么分配。')
 + cal('tip', '进阶', '① 1024 × 768 这类「2 的幂乘积」尺寸算起来非常干净，可当速算锚点；② 彩色图数据量 = 灰度图 × 通道数；③ 若要估算压缩后大小，先用「压缩比 = 原始 / 压缩后」表达（第 7 讲）；④ 记住 CSS 颜色 <code>#RRGGBB</code> 就是 24 位 RGB 的十六进制写法，能把网页开发与本节知识接起来。'))

_ck5 = (h2('方法清单')
 + h3('把一张图数字化（三步）')
 + st('采样：确定网格密度（宽 × 高），得到像素位置',
      '量化：确定每像素位数（8 位灰度 / 24 位 RGB），把连续亮度映射到有限级',
      '编码：把每个量化值写成固定长度的二进制，按行（或按通道）排列')
 + h3('算未压缩图像大小（四步）')
 + st('算像素数：<code>W × H</code>',
      '算每像素字节：<code>B / 8</code>',
      '相乘得字节数',
      '按题目口径换算：KiB 用 1024，kB 用 1000；标注「未压缩」')
 + h3('判断栅格还是矢量（两问）')
 + ck('信息是连续色调（照片、纹理）还是几何形状（线、圆、字）？',
     '是否需要任意缩放而保持清晰？',
     '两者都指向形状 + 缩放 → 矢量；否则 → 栅格')
 + h3('答题时的自查')
 + ck('写清「未压缩」与单位口径',
     '分辨率的写法是「宽 × 高」',
     '色深要说清「位怎么分配」',
     'RGB 要写清通道顺序'))

_mp5 = tb(('源文件', '位置', '覆盖的知识点'),
   ('Week5- Image Representation/Lecture5.pdf', 'p2–p3', '六个关键问题、现实的连续性 vs 计算机的离散性、数字化的三步流水线'),
   ('Week5- Image Representation/Lecture5.pdf', 'p4–p6', '数字图像定义、像素 = picture element、二维网格与 I(x, y) 记号、灰度矩阵'),
   ('Week5- Image Representation/Lecture5.pdf', 'p7–p12', '采样定义（在哪里测量）、采样网格示意、采样决定空间分辨率、分辨率写法 640×480 至 3840×2160、总像素 1920×1080=2.07MP、分辨率不等于画质'),
   ('Week5- Image Representation/Lecture5.pdf', 'p13–p18', '量化定义（给什么值）、采样与量化对照表、量化示意、灰度 0 黑 255 白、8 位 256 级、灰度图即二维数字数组'),
   ('Week5- Image Representation/Lecture5.pdf', 'p19–p20', '编码定义（怎样用位表示）、128 → 10000000、三步的分工总结'),
   ('Week5- Image Representation/Lecture5.pdf', 'p21–p25', 'RGB 模型、三元组、五种关键颜色表、24 位 = 3 字节、256^3 = 16 777 216、单像素 (255,128,0) 的二进制'),
   ('Week5- Image Representation/Lecture5.pdf', 'p26–p27', '色深定义与 2^n 表、8 位在不同分配下的不同含义'),
   ('Week5- Image Representation/Lecture5.pdf', 'p28–p31', '未压缩大小公式、1024×768 灰度 768 KiB、1920×1080 RGB 5.93 MiB、数据量 ∝ 分辨率 × 色深'),
   ('Week5- Image Representation/Lecture5.pdf', 'p32–p34', '栅格图像定义与例子、分辨率依赖与像素化、优缺点表'),
   ('Week5- Image Representation/Lecture5.pdf', 'p35–p38', '矢量图形定义、圆的数学描述、栅格与矢量六项对照、适用场景、常见格式'),
   ('Week5- Image Representation/Lecture5.pdf', 'p39–p42', '完整数字化流水线、表示 vs 编码 vs 压缩、三步一句话总结与大图'),
   ('Week5- Image Representation/Lecture5.pdf', 'p43–p50', '四道复习题（800×600 像素数、8 位级数、原始数据量、栅格或矢量），已收入本讲第十二节'),
   ('Week6- Audio and Video Representation/Exercise 3.pdf', '第 3、4、6 题', 'RGB 怎样表示颜色、位深/色深的定义与 1 位和 8 位灰度的差别、4000×3000 24 位图像的 MB 计算（本讲例 2 完整覆盖）'),
   ('（补充）', '—', '三原色与视锥细胞的感知依据、I(x,y) 到矩阵运算的衔接、CSS #RRGGBB 与十六进制的对应、MB 与 MiB 的口径差异，均为衔接性拓展'))

LEC.append(addp(C3, L(slug='w5-image-representation',
 tzh='Week 5 · 图像表示：采样、量化、编码与 RGB',
 ten='Image Representation',
 keywords=['digitization', 'sampling', 'quantization', 'pixel', 'spatial resolution',
           'megapixel', 'grayscale', 'RGB', 'colour depth', 'raster image',
           'vector graphic', 'uncompressed size'],
 files=['Week5- Image Representation/Lecture5.pdf',
        'Week6- Audio and Video Representation/Exercise 3.pdf'],
 overview=_ov5, detail=_d5a + _d5b, kws=_kw5, examples=_ex5,
 practice=_pr5, exam=_exam5, checklist=_ck5, mapping=_mp5)))

# ============================================================ Week 6
_ov6 = (h2('本节定位')
 + p('上一讲的图像是「二维空间」的信息。这一讲处理两种更复杂的信息：音频只有「一维时间」，视频是「二维空间 + 一维时间」。三者用的是同一套三步法（采样—量化—编码），只是采样的维度不同。')
 + p('本讲的另一半内容是「算数据量」。音频与视频的文件之所以大得离谱，原因可以用一条公式说清：数据量 = 采样率 × 位深 × 声道 × 时长（音频），再乘上帧率与分辨率（视频）。理解了这条公式，第 7 讲「为什么要压缩」就不用再解释了。')
 + p('与前后讲的关系：上一讲给出图像公式 <code>W × H × B / 8</code>；本讲把它扩展成音频与视频的公式；下一讲（压缩）就是针对这些「大得装不下」的数据做减法。')
 + p('学完本讲你应当能够：')
 + ck('说明声音为什么是模拟信号，以及数字化三步怎样作用于它',
      '区分采样率（每秒取样次数）与位深（每次取样用几位）',
      '用奈奎斯特准则判断给定最高频率所需的最低采样率',
      '计算未压缩音频的数据量，并说明四个影响因素',
      '说明视频是「帧的序列」，并区分帧率与分辨率',
      '计算未压缩视频的数据量，并解释它为什么比音频大几个数量级',
      '区分文件格式（容器）与编解码器（codec）'))

_d6a = (h2('一、从真实信号到数字数据')
 + h3('1.1 声音与视频本来是连续的')
 + p('课件开篇指出：声音与视频原本是<b>连续的物理信号</b>，数字化的基本过程与图像相同——连续信息必须被转换成离散的数字数据。')
 + pre('真实信号 → 采样 → 量化 → 编码 → 二进制数据')
 + h3('1.2 三种信息，三个维度')
 + p('课件用一句话把三类信息区分开，这是本讲最重要的一张对照：')
 + tb(('信息类型', '被采样的是什么', '维度'),
      ('图像 Image', '空间信息', '2 维空间'),
      ('音频 Audio', '随时间变化的声音', '1 维时间'),
      ('视频 Video', '随时间变化的图像', '2 维空间 + 1 维时间'))
 + p('维度决定了公式的形状：图像乘两个长度（宽、高），音频乘一个时间（秒），视频乘两个长度加一个时间（还乘帧率）。后面所有计算题都是这条规律的展开。')
 + h2('二、声音是什么')
 + h3('2.1 物理层面')
 + p('课件解释：我们之所以听到声音，是因为一系列<b>空气压力波</b>振动了耳膜，耳膜再把信号送给大脑。')
 + h3('2.2 设备层面')
 + p('用手机听音乐时，设备把<b>电信号</b>送给扬声器，扬声器振动产生声音。这个电信号控制扬声器膜片的运动，膜片再产生到达耳朵的压力波。')
 + p('课件的结论句很关键：<b>这个信号是声波的模拟表示</b>（"the signal is an analog representation of the sound wave"）。模拟（analog）在这里的意思是「与原始物理量连续对应」——电压随声压连续变化。')
 + h3('2.3 模拟信号的两个连续')
 + p('课件把模拟音频信号画成一条连续波形，并指出它有两个连续：')
 + ul('<b>连续的时间</b>：任何时刻都有信号值',
      '<b>连续变化的幅度</b>：值可以是任意实数')
 + p('计算机无法直接存整条连续波形。原因很硬：连续意味着无限多的点、无限精度——存储与传输都不可能。于是必须数字化。')
 + h2('三、音频的采样')
 + h3('3.1 三步流水线')
 + pre('模拟音频 → 采样 → 量化 → 编码 → 数字音频')
 + h3('3.2 采样的定义')
 + p('采样按<b>固定的时间间隔</b>测量连续信号的幅度。它回答的问题是「<b>什么时候</b>测量信号」。')
 + p('这句话与上一讲形成对照：图像采样问「在哪里（空间）」，音频采样问「在何时（时间）」。课件也明确写了：与图像不同，音频采样主要关乎<b>时间</b>。')
 + p('课件还诚实地承认代价：这种技术会丢掉一些数据，但能得到合理的声音（"This technique loses some data but produces a reasonable sound"）。丢多少、怎么丢，就是下面采样率与量化位数要控制的。')
 + h3('3.3 采样率')
 + p('采样频率（sampling frequency）：<b>每秒取的样本数</b>。单位是赫兹（Hz）。')
 + tb(('采样率', '每秒样本数', '常见用途'),
      ('8 kHz', '8 000', '电话语音'),
      ('16 kHz', '16 000', '语音识别、播客'),
      ('44.1 kHz', '44 100', 'CD 音质'),
      ('48 kHz', '48 000', '视频伴音、专业音频'))
 + h3('3.4 采样率与细节')
 + p('采样率越高，每秒的样本越多，越能准确地表示信号的变化。课件用两条疏密不同的波形对比：低采样率只在少数点取值，波峰波谷容易被「错过」；高采样率能贴近原始曲线。')
 + h3('3.5 一个直观算例')
 + p('若以 10 000 Hz 采样一段 2 秒的音频：')
 + pre('10 000 × 2 = 20 000 个样本')
 + p('注意这里只算了「样本数」，还没算每个样本占多少位。样本数 × 位深才是数据量。')
 + h3('3.6 采样率与频率内容')
 + p('声音里含不同频率成分：低频变化慢，高频变化快。要表示快速变化，采样率必须足够高——否则就会「看不清」快速振荡。')
 + h3('3.7 奈奎斯特准则')
 + p('课件给出一条基本规则：')
 + p('<b><code>f_s ≥ 2 × f_max</code></b>')
 + p('其中 f_s 是采样率，f_max 是要表示的最高频率。例：若最高频率是 20 kHz，采样率至少约 40 kHz。这条规则叫<b>奈奎斯特采样准则</b>（Nyquist sampling criterion）。')
 + p('为什么是 2 倍？直觉解释：要还原一个周期，至少要在波峰与波谷各取一个点；采样率低于 2 倍时，快速振荡会被「误读」成慢速振荡（这个现象叫混叠 aliasing）。')
 + cal('tip', '顺带理解 44.1 kHz', '人耳可听上限约 20 kHz，按奈奎斯特需要 ≥ 40 kHz。CD 选 44.1 kHz 而不是 40 kHz，是留出余量并与早期用录像机存储数字音频的工程折衷有关。这条来历属于理解性拓展，考试按 <code>f_s ≥ 2 f_max</code> 计算即可。')
 + h2('四、量化与位深')
 + h3('4.1 量化做什么')
 + p('采样之后，每个样本仍是一个连续幅度值。量化把电压（幅度）用<b>有限位数</b>表示成一个数。它回答「给每个样本什么值」。')
 + h3('4.2 采样与量化的分工')
 + tb(('过程', '主要问题', '离散化的是什么'),
      ('采样 Sampling', '什么时候测量？', '时间'),
      ('量化 Quantization', '给什么值？', '幅度'))
 + p('一句记法：<b>采样离散化时间，量化离散化振幅</b>。与图像那对（位置 / 取值）完全平行。')
 + h3('4.3 位深')
 + p('位深（bit depth）决定可能的幅度级数。n 位可表示 <code>2^n</code> 级：')
 + tb(('位深', '级数', '常见用途'),
      ('8 位', '256', '低质量语音'),
      ('16 位', '65 536', 'CD 音质'),
      ('24 位', '16 777 216', '录音棚、母带'))
 + p('位深越高，越能精确表示幅度。这与图像色深是同一个道理：位数决定量化台阶的密度，台阶越密，误差（量化噪声）越小。')
 + h3('4.4 编码')
 + p('量化得到离散数值后，编码把它们写成二进制。课件给了两个例子：')
 + pre('样本 128 → 10000000（8 位）\n样本  25 → 00011001（8 位）')
 + p('一串样本就变成一串二进制值。注意这里 128 是「量化后的中位值」，不是「128 伏」——幅度已经被映射到整数编号上了。'))

_d6b = (h2('五、声道与每秒数据量')
 + h3('5.1 单声道与立体声')
 + p('单声道（mono）只用一个声道，如 16 位、44.1 kHz、单声道。立体声（stereo）通常用两个声道：左（Left）与右（Right），每个声道有自己独立的样本序列。')
 + p('为什么要有两个声道？因为人耳靠双耳时间差与强度差判断声源方位。两个独立声道能记录这种差异，于是有了「声场」。代价是数据量翻倍。')
 + h3('5.2 每秒多少位')
 + p('课件用一个具体配置算出每秒的数据量：采样率 44.1 kHz、每样本 16 位、2 个声道。')
 + pre('44 100 × 16 × 2 = 1 411 200 位/秒\n1 411 200 / 8 = 176 400 字节/秒')
 + p('这就是「176.4 KB/s」这个常被引用的数字。第 7 讲讲压缩时，开场就会拿它当「原始数据有多大」的例子。')
 + h2('六、音频数据量公式')
 + h3('6.1 公式')
 + p('对未压缩数字音频：')
 + p('<b><code>大小（位）= f_s × B × C × T</code></b>')
 + p('其中 f_s 是采样率、B 是位深、C 是声道数、T 是时长（秒）。换成字节：')
 + p('<b><code>大小（字节）= f_s × B × C × T / 8</code></b>')
 + h3('6.2 算例：一分钟 CD 音质')
 + pre('44 100 × 16 × 2 × 60 / 8 = 10 584 000 字节\n10 584 000 / 1 048 576 ≈ 10.1 MiB')
 + p('一分钟就要 10 MiB。一小时约 606 MiB，一张 700 MB 的 CD 只能装七十多分钟——这正是 CD 容量的由来。')
 + h3('6.3 四个影响因素')
 + p('课件写成一个比例式：<b>数据量 ∝ 采样率 × 位深 × 声道数 × 时长</b>。四个量任一变大，文件就变大。')
 + tb(('参数', '调高会怎样', '代价'),
      ('采样率', '样本更密，高频细节更准', '数据量线性增大'),
      ('位深', '幅度更精确，噪声更小', '数据量线性增大'),
      ('声道数', '声场更完整', '数据量按倍数增大'),
      ('时长', '内容更长', '数据量线性增大'))
 + h2('七、从图像到视频')
 + h3('7.1 视频是什么')
 + p('课件定义：数字视频本质上是<b>随时间显示的一串图像</b>。')
 + pre('帧 1 → 帧 2 → 帧 3 → 帧 4 → …')
 + p('每一帧都是一张图像。所以：<b>视频 = 空间信息 + 时间信息</b>。')
 + h3('7.2 帧')
 + p('帧（frame）是视频序列中的一幅图像。连续播放多帧，就产生了运动的知觉。这个「知觉」很重要：视频里并没有真正运动的东西，只有一叠静态画面；运动是视觉系统补齐的。')
 + h3('7.3 帧率')
 + p('帧率（frame rate）是每秒显示或采集的帧数，单位 <b>fps</b>（frames per second）。')
 + tb(('帧率', '常见用途'),
      ('24 fps', '电影'),
      ('30 fps', '电视、网络视频'),
      ('60 fps', '游戏、体育、高动态画面'))
 + p('例如 30 fps 表示每秒表示 30 帧。帧率越高，每秒的画面越多，运动变化被记录得越频繁、越平滑。')
 + h3('7.4 帧率与运动')
 + p('低帧率下，物体在两个位置之间「跳」，中间没有记录；高帧率下，路径上有更多采样点。这与音频采样率是同一个逻辑：<b>采样越密，越快的变化越能表示</b>。')
 + h3('7.5 视频分辨率')
 + p('每一帧都有自己的空间分辨率，如 1280 × 720、1920 × 1080、3840 × 2160。例如 1920 × 1080 的视频，表示每一帧含 1920 × 1080 个像素。')
 + h3('7.6 颜色表示')
 + p('每一帧可以用 RGB 这样的颜色表示。简单的 RGB 表示：红 8 位、绿 8 位、蓝 8 位 → 每像素 24 位。图像的颜色模型原封不动搬到每一帧上。')
 + h3('7.7 视频的维度公式')
 + p('课件给了两个层次的写法：')
 + pre('图像：宽 × 高\n视频：宽 × 高 × 时间\n更具体：视频 = 帧宽 × 帧高 × 帧率 × 时长')
 + h2('八、视频数据量公式')
 + h3('8.1 公式')
 + p('<b><code>大小（位）= W × H × B × F × T</code></b>')
 + p('其中 W、H 是帧尺寸，B 是每像素位数，F 是帧率，T 是时长（秒）。字节数除以 8：')
 + p('<b><code>大小（字节）= W × H × B × F × T / 8</code></b>')
 + h3('8.2 算例：1080p、10 秒')
 + p('配置：1920 × 1080、24 位 RGB、30 fps、10 秒。课件分三步算：')
 + pre('一帧：1920 × 1080 × 24 / 8 = 6 220 800 字节\n一秒：6 220 800 × 30 = 186 624 000 字节\n十秒：1 866 240 000 字节 ≈ 1.74 GiB')
 + p('十秒就 1.74 GiB。课件用一句总结：<b>这就是为什么原始视频数据可能极大</b>。')
 + h3('8.3 决定因素')
 + p('比例式：<b>数据量 ∝ 分辨率 × 色深 × 帧率 × 时长</b>。四项相乘，因此视频数据会「非常快地增长」——把分辨率从 720p 提到 1080p，像素数变成 2.25 倍；再提帧率、再提色深，很快就到「每秒几百 MB」。')
 + h3('8.4 与音频的量级对比')
 + p('同一秒内：CD 音质音频约 176 KB，1080p 视频约 187 MB。差一千倍以上。这解释了为什么视频必须压缩（第 7 讲），而音频压缩的紧迫性略低（但也很大）。')
 + h2('九、多媒体文件里有什么')
 + h3('9.1 视频文件不只是画面')
 + p('课件指出一个多媒体视频可能包含：')
 + ul('视觉信息 → 帧',
      '音频信息 → 音频样本')
 + p('所以一个视频文件里可能有：视频流、音频流、元数据、其他信息。这已经预告了第 4 章「文件格式 vs 容器 vs 编解码器」的区分。')
 + h3('9.2 音频与视频的对照')
 + tb(('对照项', '音频 Audio', '视频 Video'),
      ('主要信息', '声音', '视觉 + 声音'),
      ('采样维度', '时间', '空间 + 时间'),
      ('基本单位', '样本（sample）', '帧（frame）'),
      ('主要速率', '采样率', '帧率'),
      ('空间分辨率', '不适用', '宽 × 高'),
      ('数值含义', '样本幅度', '像素值'))
 + h3('9.3 常见格式')
 + p('音频格式：WAV、AIFF、MP3、AAC、FLAC。视频格式：MP4、WebM、MOV、AVI、MKV。')
 + p('课件强调：<b>文件格式与压缩算法或编解码器不是同一件事</b>。MP4 是容器（能装 H.264 视频 + AAC 音频），H.264 是视频编码标准，AAC 是音频编码格式。三者可自由组合，这正是「格式 ≠ 编码」的含义。')
 + h2('十、为什么音视频文件这么大')
 + p('课件分两段解释，逻辑一样：<b>每个参数都在乘</b>。')
 + p('<b>原始音频</b>取决于采样率、位深、声道数、时长：录得越久样本越多；采样率越高每秒样本越多；位深越高每样本位越多。')
 + p('<b>原始视频</b>同时叠加了高空间分辨率、颜色信息、每秒很多帧、较长时长。仅 1920 × 1080 × 24 位 × 30 fps 就已经产生极大的原始数据量。')
 + h2('十一、统一视角')
 + p('课件最后把三类信息并排，强调同一条原理：')
 + pre('真实信息 → 采样 → 量化 → 编码 → 数字数据')
 + tb(('信息', '采样维度', '采样参数', '量化参数'),
      ('图像', '空间', '分辨率（宽 × 高）', '色深（每像素位数）'),
      ('音频', '时间', '采样率（Hz）', '位深（每样本位数）'),
      ('视频', '空间 + 时间', '分辨率 + 帧率', '色深'))
 + p('这张表值得背下来：考试里「为什么视频数据量比音频大」的答案就在「维度多一层、每层都在乘」。')
 + h2('十二、课件小测（附答案）')
 + ol('44.1 kHz 的录音一秒取多少样本？→ <code>44.1 × 1000 = 44 100</code> 个',
      '16 位样本有多少量化级？→ <code>2^16 = 65 536</code> 级',
      '16 位、44.1 kHz、单声道、10 秒的原始大小？→ <code>44 100 × 16 × 1 × 10 / 8 = 882 000</code> 字节',
      '30 fps 的视频 20 秒有多少帧？→ <code>30 × 20 = 600</code> 帧',
      '1280 × 720、24 位、30 fps 的一秒原始数据？→ <code>1280 × 720 × 24 × 30 / 8 = 82 944 000</code> 字节 ≈ 79.1 MiB'))

_kw6 = K(('analog signal', '模拟信号', 'A signal that is continuous in time and in amplitude.'),
         ('sampling rate (sampling frequency)', '采样率', 'Number of samples taken per second, in hertz.'),
         ('bit depth', '位深', 'Number of bits per sample; gives 2^n amplitude levels.'),
         ('quantization level', '量化级', 'One of the finite amplitude values a sample can take.'),
         ('Nyquist criterion', '奈奎斯特准则', 'The sampling rate must be at least twice the highest frequency to be represented.'),
         ('aliasing', '混叠', 'A fast signal misread as a slow one when the sampling rate is too low.'),
         ('mono', '单声道', 'One audio channel, e.g. 16-bit, 44.1 kHz, mono.'),
         ('stereo', '立体声', 'Two channels (left and right), each with its own sample sequence.'),
         ('frame', '帧', 'One image in a video sequence.'),
         ('frame rate', '帧率', 'Number of frames per second (fps).'),
         ('video resolution', '视频分辨率', 'Width × height of each frame.'),
         ('container', '容器', 'A file that packages media streams and metadata, e.g. MP4.'),
         ('codec', '编解码器', 'An algorithm that encodes and decodes a media stream, e.g. H.264 or AAC.'),
         ('uncompressed audio size', '未压缩音频大小', 'f_s × B × C × T / 8 bytes.'),
         ('uncompressed video size', '未压缩视频大小', 'W × H × B × F × T / 8 bytes.'))

_ex6 = (qa('例 1　算 44.1 kHz、16 位、立体声、60 秒的未压缩音频大小，并换算成 MiB。',
    p('<b>第一步，算每秒样本数：</b><code>44 100</code> 个/秒。')
    + p('<b>第二步，算每秒位数：</b><code>44 100 × 16 × 2 = 1 411 200</code> 位/秒（两个声道各算一遍）。')
    + p('<b>第三步，乘时长：</b><code>1 411 200 × 60 = 84 672 000</code> 位。')
    + p('<b>第四步，转字节：</b><code>84 672 000 / 8 = 10 584 000</code> 字节。')
    + p('<b>第五步，换算：</b><code>10 584 000 / 1 048 576 ≈</code> <b>10.1 MiB</b>（十进制约 10.58 MB）。')
    + p('也可以直接用公式一步：<code>44 100 × 16 × 2 × 60 / 8</code>。两种写法结果相同，考试时写公式再代值更不容易错。')
    + p('检算技巧：<code>44 100 × 16 × 2 / 8 = 176 400</code> 字节/秒，乘 60 得 10 584 000。先算「每秒多少字节」这个中间量，后面所有题都能复用。'))
  + qa('例 2　算 1000 × 800、24 位、50 fps、10 秒、无音轨的视频大小（按 1 GB = 10^9 字节）。',
    p('<b>第一步，一帧多少字节：</b><code>1000 × 800 × 24 / 8 = 2 400 000</code> 字节。')
    + p('<b>第二步，一秒多少字节：</b><code>2 400 000 × 50 = 120 000 000</code> 字节。')
    + p('<b>第三步，乘时长：</b><code>120 000 000 × 10 = 1 200 000 000</code> 字节。')
    + p('<b>第四步，换算：</b><code>1 200 000 000 / 10^9 =</code> <b>1.2 GB</b>。')
    + p('这与 Exercise 3 第 8 题同型。注意题目若按 GiB 计，则 <code>1 200 000 000 / 1 073 741 824 ≈ 1.12 GiB</code>——两种口径都要会，看题干给的是哪一种。')
    + p('量级检验：10 秒就 1.2 GB，说明一小时未压缩视频约 430 GB，任何存储介质都受不了，必须压缩。'))
  + qa('例 3　算 50 kHz、24 位、立体声、一分钟的音频大小（按 1 MB = 10^6 字节）。',
    p('<code>50 kHz = 50 000</code> 个样本/秒；每样本 24 位 = 3 字节；两个声道；60 秒。')
    + p('<b>公式代入：</b><code>50 000 × 24 × 2 × 60 / 8 = 18 000 000</code> 字节。')
    + p('<b>验算中间量：</b><code>50 000 × 3 × 2 = 300 000</code> 字节/秒；<code>300 000 × 60 = 18 000 000</code>，一致。')
    + p('<b>换算：</b><code>18 000 000 / 10^6 =</code> <b>18 MB</b>。')
    + p('注意这道题的三个参数同时都偏高（采样率高于 CD、位深高于 CD、双声道），所以是 CD 音质的 1.7 倍左右。凡是「参数都变高」的题，结果一定明显大于基准值，可用来快速验算。'))
  + qa('例 4　某信号的最高频率是 15 kHz。按奈奎斯特准则，采样率至少要多少？若实际用 8 kHz 会怎样？',
    p('<b>第一步，套公式：</b><code>f_s ≥ 2 × f_max = 2 × 15 000 = 30 000</code> Hz，即至少 <b>30 kHz</b>。')
    + p('<b>第二步，判断实际值：</b>8 kHz &lt; 30 kHz，不满足准则。')
    + p('<b>第三步，说明后果：</b>高于 4 kHz 的频率成分无法被正确表示，会被「折叠」到低频区，产生与原始信号不符的成分——这就是混叠（aliasing）。听感上是金属味、哨音或失真。')
    + p('<b>第四步，给补救：</b>要么提高采样率到 30 kHz 以上，要么在采样前用低通滤波器把 4 kHz 以上的成分滤掉（抗混叠滤波），让信号本身满足准则。')
    + p('这道题的迁移点：任何「给定最高频率求采样率」的题都是乘 2；「给定采样率求可表示的最高频率」是除 2。')))

_pr6 = (ol('44.1 kHz 的采样率，一秒取多少个样本？样本之间相隔多少微秒？',
          '16 位与 24 位分别有多少量化级？',
          '算 16 位、44.1 kHz、单声道、10 秒的未压缩字节数。',
          '30 fps 的视频，20 秒共多少帧？若帧率改为 24 fps 呢？',
          '算 1280 × 720、24 位、30 fps 的一秒原始数据量，并换算成 MiB。',
          '把采样率从 44.1 kHz 提到 48 kHz，其他参数不变，数据量增加多少百分比？')
 + det('参考答案与思路',
    p('<b>1.</b> 44.1 kHz = <b>44 100</b> 个样本/秒。相邻样本间隔 <code>1 / 44 100 ≈ 22.7 µs</code>（约 0.0000227 秒）。这一小问考的是「kHz 要乘 1000」，写成 4 410 或 441 000 都是常见错。')
    + p('<b>2.</b> <code>2^16 = 65 536</code> 级；<code>2^24 = 16 777 216</code> 级。位数每加 1，级数翻倍。')
    + p('<b>3.</b> <code>44 100 × 16 × 1 × 10 / 8 = 882 000</code> 字节（约 861 KiB）。')
    + p('<b>4.</b> 30 fps × 20 s = <b>600 帧</b>；24 fps × 20 s = <b>480 帧</b>。帧率降低会减少数据量，但运动连贯性变差。')
    + p('<b>5.</b> <code>1280 × 720 × 24 × 30 / 8 = 82 944 000</code> 字节；<code>/ 1 048 576 ≈ 79.1 MiB</code>。')
    + p('<b>6.</b> 只改采样率，数据量按同一比例变：<code>48 000 / 44 100 ≈ 1.088</code> → 增加约 <b>8.8%</b>。这类「只改一个参数」的题，直接用比值算，不必重算绝对值。')))

_exam6 = (cal('exam', '必考', '① 采样率与位深的定义与分工（时间 vs 幅度）；② <code>f_s × B × C × T / 8</code> 与 <code>W × H × B × F × T / 8</code> 两条公式；③ 单位换算（kHz、MiB、MB、GB）；④ 奈奎斯特 <code>f_s ≥ 2 f_max</code>；⑤ 帧、帧率、分辨率三者的关系；⑥ 容器与编解码器的区别。')
 + cal('warn', '易错 1', '把 44.1 kHz 当成 44 100 之外的值，或忘记乘 1000。凡是 kHz 都要乘 1000 换成 Hz。')
 + cal('warn', '易错 2', '立体声忘记乘 2。声道数是公式里最容易漏的一项。')
 + cal('warn', '易错 3', '算视频时忘记乘帧率，或把「帧率 × 时长」当成帧数以外的量。正确顺序：一帧字节 → 一秒字节 → 总字节。')
 + cal('warn', '易错 4', '把 MP4 当成一种编码。MP4 是容器，里面可以装 H.264 视频与 AAC 音频。')
 + cal('tip', '进阶', '① 先算「每秒字节数」这个中间量，所有题都能复用；② 只改一个参数时用比值算增量，速度快且不易错；③ 奈奎斯特给的是下限，实际系统会取更高（CD 取 44.1 kHz 而非 40 kHz）；④ 抗混叠滤波器的作用是「采样前先限制带宽」，属于工程补充。'))

