 + h2('二、内存与存储')
 + h3('2.1 一张对照表')
 + tb(('对照项', '内存（RAM）', '存储（SSD / HDD）'),
      ('存什么', '当前正在使用的数据', '留待以后使用的数据'),
      ('易失性', '通常是易失的（volatile）', '非易失（non-volatile）'),
      ('速度', '通常更快', '相对较慢'),
      ('容量与持久性', '通常较小', '通常更大且持久'))
 + p('课件补了一句限定：在计算机体系结构里 memory 一词含义更广，这里主要以 RAM 为例。这个限定很重要——严格说 cache 也是 memory，但本节要对比的是「工作区 vs 仓库」。')
 + h3('2.2 易失与非易失')
 + p('<b>易失（volatile）</b>：断电后数据通常消失。<b>非易失（non-volatile）</b>：不需要持续供电也能保留数据。')
