 + p('课件留了一个小问题：<b>RAM 适合作为保存学生论文的唯一位置吗？</b>显然不适合——断电、崩溃、关机都会让论文消失。正确做法是「在 RAM 里编辑，随时保存到存储介质，并保留备份」。')
