 + p('课件的提示句：<b>KB 与 KiB 并不完全相等，MB 与 MiB 也不完全相等；计算前先确认题目用的是哪种单位</b>。')
 + cal('exam', '为什么会「买来少了一截」', '厂商按十进制标 1 TB = 10^12 字节；操作系统按二进制算，<code>10^12 / 1024^4 ≈ 0.909 TiB</code>。于是 1 TB 硬盘在系统里显示约 931 GiB。这不是「缺斤少两」，而是两种口径。')
 + h3('3.4 文件大小的大致感觉')
 + p('课件给了四个参照：')
