 + p('课件给的例子：MP4 常用作媒体容器，H.264 是视频编码标准，AAC 是音频编码格式；一个 MP4 文件里可以有 H.264 编码的视频与 AAC 编码的音频。')
 + p('课件强调三者相关但<b>不能互换</b>。这条区分直接来自第 6 讲的「格式 ≠ 编解码器」，本讲把它补全成三方关系。')
 + h3('7.8 格式为什么重要')
