# ============================================================ Week 11
_ov11 = (h2('本节定位')
 + p('前面十讲都在处理「数据」：怎么表示、怎么存、怎么找、怎么加密。这一讲处理「判断」：信息怎样被写成可以判真假的语句，再用逻辑运算组合起来。这是所有条件语句、权限规则、数据库查询、电路设计的共同语言。')
 + p('本节的技术核心只有两件：<b>真值表</b>与<b>等价律</b>。真值表把「一个表达式在什么情况下为真」穷举出来；等价律让你不必穷举就能化简与变形。前者是验证工具，后者是计算工具，二者配合才能既算得对又算得快。')
 + p('与前几讲的衔接：第 4 讲讲字符编码时提到「字节不知道自己是什么编码」，本讲说「一句话本身不含真值，真值来自它的解释」；第 5 章讲 AES 的轮函数、OTP 的 XOR，都是本讲逻辑运算的直接应用；第 9 讲的布尔检索 AND/OR/NOT，就是本讲运算符的集合版本。')
 + p('学完本讲你应当能够：')
 + ck('判断一个语句是不是命题，并说出理由',
      '写出六个运算符（¬ ∧ ∨ ⊕ → ↔）的真值表',
      '说明蕴含「只有前件真、后件假时才为假」的道理',
      '为 n 个命题的表达式列出 2^n 行真值表并逐步求值',
      '把自然语言条件翻译成逻辑表达式，反之亦然',
      '用等价律（含 De Morgan、分配律）化简表达式',
      '把逻辑表达式落到程序条件、SQL 条件、数字电路与访问控制上'))

_d11a = (h2('一、什么是逻辑')
 + h3('1.1 定义')
 + p('课件的定义很短：逻辑是<b>研究正确推理</b>的学科；它提供规则来判断一个陈述或结论是真还是假；它帮我们依据已有信息做决定。')
 + h3('1.2 计算中逻辑做四件事')
 + ul('用形式化的方式表示信息',
      '表达条件与关系',
      '判断条件是真还是假',
      '支撑决策与自动推理')
 + h3('1.3 三个日常判断')
 + p('课件给的三个例子：判断用户是否有权访问系统、判断学生是否通过考试、判断文件是否存在且可读。三个都是「若干条件组合 → 一个真假结论」的结构。')
 + h3('1.4 五个应用领域')
 + tb(('领域', '逻辑在做什么'),
      ('编程', '条件语句与决策'),
      ('数字电路', '逻辑门与布尔运算'),
      ('数据库', '用逻辑条件筛选记录'),
      ('人工智能', '知识表示与推理'),
      ('信息安全', '访问控制与权限检查'))
 + p('这五个领域在后面的小节里会逐一落地（第十二节）。')
 + h2('二、命题')
 + h3('2.1 定义')
 + p('<b>命题（proposition）</b>是<b>具有确定真值</b>的陈述句：要么真，要么假。')
 + p('定义里有两个条件都必须满足：是<b>陈述句</b>（不是疑问、不是命令），且有<b>确定真值</b>（不依赖未知变量的取值）。')
 + h3('2.2 判断题')
 + tb(('语句', '是命题吗', '理由'),
      ('地球绕太阳转。', '是', '陈述句，真值确定（真）'),
      ('5 大于 3。', '是', '陈述句，真值确定（真）'),
      ('地球是平的，且月亮绕火星转。', '是', '复合陈述句，真值确定（假）'),
      ('赫尔辛基在芬兰。', '是', '陈述句，真值确定（真）'),
      ('现在几点了？', '不是', '疑问句，无真值'),
      ('请关门。', '不是', '祈使句，无真值'),
      ('x + 2 = 5', '本身不是', '含自由变量，取值未定时真值不定'))
 + p('最后一行是本节的边界情形：<code>x + 2 = 5</code> 本身不是命题，因为 x 未定；一旦说「当 x = 3 时，x + 2 = 5」，它就变成命题（真）。这类含变量的表达式叫<b>谓词</b>（predicate），需要第 6 章之外的量词理论来处理——本课不涉及，只要会说「不是命题」并给出理由。')
 + h3('2.3 真值')
 + p('在经典命题逻辑里，一个命题只有两种真值：<b>真（True, T）</b>与<b>假（False, F）</b>。')
 + tb(('命题', '真值'),
      ('2 + 3 = 5', 'T'),
      ('10 是奇数', 'F'),
      ('地球是行星', 'T'),
      ('7 小于 4', 'F'))
 + p('常用符号表示命题，例如 P：正在下雨；Q：路面是湿的。后面的所有公式都用这种「字母代表句子」的写法。')
 + h3('2.4 原子命题与复合命题')
 + tb(('类型', '定义', '例子'),
      ('原子命题（atomic）', '在当前逻辑表示下不能再分成更小命题的简单命题', 'P：正在下雨。'),
      ('复合命题（compound）', '由一个或多个命题用逻辑运算符组合而成', '<code>P ∧ Q</code>：正在下雨且路面是湿的。'))
 + p('课件的另外三个复合命题例子：用户已登录或有访客权限；文件存在且可读；学生通过考试且完成作业。三个都是「两个条件 + 一个运算符」的形状，正是访问控制里的典型规则。')
 + h2('三、六个逻辑运算符')
 + h3('3.1 总表')
 + tb(('名称', '符号', '含义'),
      ('否定 NOT', '<code>¬P</code>', 'negation'),
      ('合取 AND', '<code>P ∧ Q</code>', 'conjunction'),
      ('析取 OR', '<code>P ∨ Q</code>', 'disjunction'),
      ('异或 XOR', '<code>P ⊕ Q</code>', 'exclusive OR'),
      ('蕴含 Implication', '<code>P → Q</code>', 'if P, then Q'),
      ('双条件 Biconditional', '<code>P ↔ Q</code>', 'P if and only if Q'))
 + p('符号记法要熟：¬ 是否定，∧ 像字母 A（and），∨ 像字母 V（OR 的 v），⊕ 是带圈的加号（异或），→ 是箭头（推出），↔ 是双向箭头（当且仅当）。')
 + h3('3.2 否定 NOT')
 + p('否定翻转真值：P 真则 ¬P 假，P 假则 ¬P 真。例：P「计算机在运行」，<code>¬P</code>「计算机没有在运行」。')
 + tb(('P', '¬P'), ('T', 'F'), ('F', 'T'))
 + h3('3.3 合取 AND')
 + p('合取<b>只有两个命题都真时才真</b>。例：P「用户有有效账号」，Q「用户输入了正确密码」，<code>P ∧ Q</code> 表示两者都成立。')
 + tb(('P', 'Q', 'P ∧ Q'),
      ('T', 'T', 'T'), ('T', 'F', 'F'), ('F', 'T', 'F'), ('F', 'F', 'F'))
 + h3('3.4 析取 OR')
 + p('析取<b>至少一个为真就真</b>。例：P「用户用密码登录」，Q「用户用安全密钥登录」，<code>P ∨ Q</code> 表示任一方式即可。')
 + tb(('P', 'Q', 'P ∨ Q'),
      ('T', 'T', 'T'), ('T', 'F', 'T'), ('F', 'T', 'T'), ('F', 'F', 'F'))
 + p('注意第一行：两个都为真时，OR 也为真。这一点常被误解为「二选一」，那是 XOR 的语义。')
 + h3('3.5 异或 XOR')
 + p('异或<b>恰有一个为真时</b>才真。例：系统要求用户在两种验证方式中恰好选一种。')
 + tb(('P', 'Q', 'P ⊕ Q'),
      ('T', 'T', 'F'), ('T', 'F', 'T'), ('F', 'T', 'T'), ('F', 'F', 'F'))
 + p('课件把差别写成两句：<b>OR 是至少一个真；XOR 是恰好一个真</b>。差别只出现在「两个都真」这一行。')
 + h3('3.6 蕴含')
 + p('蕴含「若 P 则 Q」：P 叫<b>前件</b>（antecedent），Q 叫<b>后件</b>（consequent）。')
 + p('例子：P「学生通过考试」，Q「学生拿到及格成绩」，<code>P → Q</code> 表示「若学生通过考试，则拿到及格成绩」。')
 + p('课件的关键规则：<b>蕴含只在前件真、后件假时为假</b>。')
 + tb(('P', 'Q', 'P → Q'),
      ('T', 'T', 'T'), ('T', 'F', 'F'), ('F', 'T', 'T'), ('F', 'F', 'T'))
 + h3('3.7 双条件')
 + p('双条件 <code>P ↔ Q</code>：P 真当且仅当 Q 真。两个命题<b>必须真值相同</b>。')
 + p('例子：一个数是偶数，当且仅当它能被 2 整除。')
 + tb(('P', 'Q', 'P ↔ Q'),
      ('T', 'T', 'T'), ('T', 'F', 'F'), ('F', 'T', 'F'), ('F', 'F', 'T'))
 + p('对比 XOR 的表：双条件与异或恰好相反。这不是巧合——<code>P ↔ Q</code> 等价于 <code>¬(P ⊕ Q)</code>。')
 + h2('四、真值表')
 + h3('4.1 定义')
 + p('真值表（truth table）列出逻辑表达式在<b>命题真值的每一种组合</b>下的取值。')
 + h3('4.2 有什么用')
 + ul('理解各个运算符的语义',
      '求复合命题的真值',
      '检查两个表达式是否逻辑等价',
      '分析程序与数字电路中的条件')
 + h3('4.3 行数公式')
 + p('两个命题有 <code>2^2 = 4</code> 种组合。一般地：')
 + p('<b><code>n 个独立命题 → 2^n 行</code></b>')
 + tb(('命题数', '行数'),
      ('1', '2'), ('2', '4'), ('3', '8'), ('4', '16'))
 + p('这个公式与第 1 讲的 <code>2^n</code> 是同一个：每个命题是一位，取值组合就是位模式。所以三条命题的 8 行可以按 <code>000, 001, 010 … 111</code> 顺序列，永不会漏行。')
 + h3('4.4 构造步骤')
 + st('列出所有命题的所有真值组合（按位模式顺序，最左列变化最慢）',
      '为每个中间子表达式单独开一列',
      '按运算符逐列计算，右边列依赖左边列',
      '最后一列是最终结果，检查行数是否为 <code>2^n</code>')
 + p('课件用 <code>P ∧ Q</code> 示范：先列 P、Q 的四种组合，再套 AND。这个流程看着简单，但「列全组合」和「逐步计算中间列」是两条最常见的失分点。'))

_d11b = (h2('五、为什么 P 为假时蕴含为真')
 + p('这是学生最常问的一个点，课件专门用一页解释。例子仍是「若学生通过考试，则拿到及格成绩」。')
 + p('假设学生没有通过考试。条件「学生通过考试」为假。此时这句声明<b>没有对「未通过时会发生什么」作出任何断言</b>——它没说未通过的人一定不及格，也没说一定及格。')
 + p('因此这个蕴含被视为真。课件把规则写成一句：<b>蕴含只在前件为真的情况下提出要求</b>（"An implication makes a requirement only for the case where its antecedent is true"）。')
 + cal('tip', '记法', '把 <code>P → Q</code> 想成一条<b>合同条款</b>：只有「P 成立」时才要求「Q 成立」。P 不成立时条款没被触发，因此不构成违约（即不为假）。这就是逻辑里说的「真空真」（vacuous truth）。')
 + p('这个性质有实际后果：如果你写 <code>if 条件: 断言</code>，而条件从不成立，那么这条断言永远「没被违反」，测试也就永远通不过失败用例——看似正确，实则没测到东西。')
 + h2('六、复合表达式与优先级')
 + h3('6.1 括号决定分组')
 + p('逻辑表达式可以组合多个运算符。例：')
 + pre('P ∧ Q ∨ R')
 + p('课件指出这个表达式在第一处读法下为真，当且仅当「P 与 Q 都真」或「R 真」；换一种分组（<code>P ∧ (Q ∨ R)</code>）则是「P 真，且 Q 或 R 至少一个真」。')
 + p('<b>括号决定表达式怎样分组</b>——这句话是本小节的核心。同一个符号串，分组不同，含义不同。')
 + h3('6.2 优先级')
 + p('不用括号时，运算符按优先级结合。课件的常用顺序：')
 + st('NOT（¬）',
      'AND（∧）',
      'OR（∨）',
      '蕴含（→）',
      '双条件（↔）')
 + p('例子：<code>¬P ∧ Q</code> 解释为 <code>(¬P) ∧ Q</code>，不是 <code>¬(P ∧ Q)</code>。')
 + p('课件的建议：<b>用括号把表达式写清楚，避免歧义</b>。这条建议在写程序时尤其重要——不同语言对 and/or 的优先级处理略有差异，加括号永远不会错。')
 + h3('6.3 三命题的八行真值表')
 + p('课件用 <code>P ∧ Q ∨ ¬R</code> 示范（按优先级即 <code>(P ∧ Q) ∨ (¬R)</code>）。三个命题 → 8 行，中间列先算 <code>P ∧ Q</code>，再算 <code>¬R</code>，最后算 OR：')
 + tb(('P', 'Q', 'R', 'P ∧ Q', '¬R', '结果'),
      ('T', 'T', 'T', 'T', 'F', 'T'),
      ('T', 'T', 'F', 'T', 'T', 'T'),
      ('T', 'F', 'T', 'F', 'F', 'F'),
      ('T', 'F', 'F', 'F', 'T', 'T'),
      ('F', 'T', 'T', 'F', 'F', 'F'),
      ('F', 'T', 'F', 'F', 'T', 'T'),
      ('F', 'F', 'T', 'F', 'F', 'F'),
      ('F', 'F', 'F', 'F', 'T', 'T'))
 + p('逐行核对方法：先算两列的与，再算第三列的否，最后一列取「或」。注意第 1 行：<code>P ∧ Q</code> 为 T，所以整体为 T，与 <code>¬R = F</code> 无关——OR 只要一边真。')
 + h3('6.4 另一个例子：P → Q ∧ R')
 + p('课件用 <code>P → (Q ∧ R)</code> 示范要先算 <code>Q ∧ R</code> 再算蕴含：')
 + tb(('P', 'Q', 'R', 'Q ∧ R', '结果'),
      ('T', 'T', 'T', 'T', 'T'),
      ('T', 'T', 'F', 'F', 'F'),
      ('T', 'F', 'T', 'F', 'F'),
      ('T', 'F', 'F', 'F', 'F'),
      ('F', 'T', 'T', 'T', 'T'),
      ('F', 'T', 'F', 'F', 'T'),
      ('F', 'F', 'T', 'F', 'T'),
      ('F', 'F', 'F', 'F', 'T'))
 + p('课件的观察句：<b>当 P 为假时，蕴含总是真</b>。看表的后四行，全是 T。这不是巧合，而是第五节那条规则的表征。')
 + h2('七、把英文句子翻译成逻辑表达式')
 + p('课件给了一组变量与一张对照表：')
 + pre('P：用户有有效账号\nQ：用户有权限\nR：资源是公开的')
 + tb(('英文句子', '逻辑表达式'),
      ('用户有账号且有权限。', '<code>P ∧ Q</code>'),
      ('用户有账号或有权限。', '<code>P ∨ Q</code>'),
      ('用户没有权限。', '<code>¬Q</code>'),
      ('如果用户有账号，那么用户有权限。', '<code>P → Q</code>'),
      ('用户有账号当且仅当用户有权限。', '<code>P ↔ Q</code>'))
 + p('翻译的关键是把「连接词」认准：and → ∧、or → ∨、not → ¬、if…then → →、if and only if → ↔。中文里的「且」「并且」「同时」都是 ∧；「或」「或者」都是 ∨（注意中文的「或」通常含「两者皆可」，即 inclusive OR）。')
 + h2('八、逐步求值')
 + p('课件给了一个完整的求值例子：')
 + pre('表达式：P ∨ Q ∧ ¬R\n已知：P = False，Q = True，R = False')
 + st('先算括号（若有）；这里先算 <code>P ∨ Q</code>：<code>F ∨ T = T</code>',
      '算 <code>¬R</code>：<code>¬F = T</code>',
      '算 AND：<code>T ∧ T = T</code>',
      '最终结果：真')
 + p('这个例子里，课件的分组是 <code>(P ∨ Q) ∧ ¬R</code>。若按第五节的标准优先级（AND 先于 OR），原式应读作 <code>P ∨ (Q ∧ ¬R)</code>，结果是 <code>F ∨ (T ∧ T) = F ∨ T = T</code>——恰好也是真，但过程不同。')
 + cal('warn', '要注意的地方', '这个例子的两种分组都得 T，所以结果看不出差别；换一组取值就会分歧。因此做题时<b>先明确括号</b>，或按题目给的优先级表执行，不要凭感觉。考试若给了括号，就严格按括号。')
 + h2('九、构造真值表时的常见错误')
 + p('课件列了五条：')
 + ul('漏掉一种或多种真值组合',
      '把 OR 与 XOR 混为一谈',
      '只要 P 为假就把蕴含判为假',
      '忽略运算符优先级',
      '不先算中间结果，直接写最终列')
 + p('并给了四条良好做法：')
 + ck('先把所有输入组合列全（按位模式排）',
     '为每个中间结果单独开一列',
     '严格遵守括号与优先级',
     '最后逐行复核一遍（尤其最后一行与前一行）')
 + h2('十、逻辑等价')
 + h3('10.1 定义')
 + p('若两个逻辑表达式在命题真值的<b>每一种组合</b>下取值都相同，则它们<b>逻辑等价</b>。记号 <code>P ≡ Q</code>。')
 + h3('10.2 一个基本等价式')
 + p('课件的第一个例子：')
 + p('<b><code>P → Q ≡ ¬P ∨ Q</code></b>')
 + tb(('P', 'Q', 'P → Q', '¬P ∨ Q'),
      ('T', 'T', 'T', 'T'),
      ('T', 'F', 'F', 'F'),
      ('F', 'T', 'T', 'T'),
      ('F', 'F', 'T', 'T'))
 + p('两列完全相同，所以等价。这条式子极有用：它把「蕴含」消掉了，而 ∧ ∨ ¬ 是电路能直接实现的基本运算。')
 + p('课件强调：<b>真值表可以用来验证逻辑等价</b>。这也是真值表最重要的用途——不是算某一行，而是比较两个表达式。')
 + h3('10.3 恒等律与支配律')
 + tb(('名称', '式子', '意思'),
      ('恒等律 Identity', '<code>P ∧ T ≡ P</code>；<code>P ∨ F ≡ P</code>', '与真「且」不变；与假「或」不变'),
      ('支配律 Domination', '<code>P ∨ T ≡ T</code>；<code>P ∧ F ≡ F</code>', '与真「或」恒真；与假「且」恒假'))
 + p('记忆法：T 是「吸收元」在 OR 上，F 是「吸收元」在 AND 上。')
 + h3('10.4 双重否定')
 + p('<b><code>¬¬P ≡ P</code></b>：连做两次 NOT 回到原值。')
 + p('课件的例子：P「系统可用」，¬P「系统不可用」，<code>¬(¬P)</code>「系统并非不可用」——最终真值与 P 相同。')
 + h3('10.5 德摩根律')
 + p('两条极重要的等价式：')
 + p('<b><code>¬(P ∧ Q) ≡ ¬P ∨ ¬Q</code></b>　　<b><code>¬(P ∨ Q) ≡ ¬P ∧ ¬Q</code></b>')
 + p('课件的解释：NOT (P AND Q) 等价于 NOT P OR NOT Q；NOT (P OR Q) 等价于 NOT P AND NOT Q。')
 + p('课件给了一个自然语言例子：「并非（账号有效且密码正确）」等价于「账号无效，或者密码不正确」。')
 + p('为什么这很重要？因为程序里把条件取反时最容易出错：')
 + pre('if not (a and b):    等价于   if (not a) or (not b):')
 + p('而写成 <code>if (not a) and (not b):</code> 是错的——那是 <code>¬(a ∨ b)</code> 的意思，条件被收得更紧了。')
 + h3('10.6 交换律与结合律')
 + tb(('名称', '式子'),
      ('交换律 Commutative', '<code>P ∧ Q ≡ Q ∧ P</code>；<code>P ∨ Q ≡ Q ∨ P</code>'),
      ('结合律 Associative', '<code>(P ∧ Q) ∧ R ≡ P ∧ (Q ∧ R)</code>；<code>(P ∨ Q) ∨ R ≡ P ∨ (Q ∨ R)</code>'))
 + p('这两条让「多个 ∧ 连写」与顺序无关，于是可以随便重排、分组——是化简与电路优化的基础。')
 + h3('10.7 分配律')
 + p('AND 与 OR 可以互相分配：')
 + p('<b><code>P ∧ (Q ∨ R) ≡ (P ∧ Q) ∨ (P ∧ R)</code></b>')
 + p('<b><code>P ∨ (Q ∧ R) ≡ (P ∨ Q) ∧ (P ∨ R)</code></b>')
 + p('与算术不同，这里两个方向都成立（算术里只有乘法对加法分配，加法对乘法不分配）。这一点是布尔代数与普通代数最大的差别之一。')
 + h3('10.8 化简')
 + p('课件给了三个化简例子：')
 + ol('<code>P ∧ T ≡ P</code>（恒等律）',
      '<code>¬(P ∧ Q) ≡ ¬P ∨ ¬Q</code>（德摩根）',
      '<code>(P ∧ Q) ∨ (P ∧ R) ≡ P ∧ (Q ∨ R)</code>（分配律反向使用）')
 + p('为什么要化简？课件给了三个理由：让条件更容易理解、减少不必要的运算、支撑高效数字电路的设计。第三条最实在：电路里每一个运算符都是几个晶体管，化简直接省芯片面积与功耗。'))

_d11c = (h2('十一、逻辑在系统中的应用')
 + h3('11.1 程序里的条件')
 + p('课件给了一个访问控制条件：')
 + pre('P：用户是管理员\nQ：用户有权访问该文件\nR：文件是公开的')
 + p('用户可访问当且仅当：')
 + p('<b><code>P ∨ (Q ∧ R)</code></b>')
 + p('对应的 Python 代码：')
 + pre('if (is_admin or has_permission) and is_public:\n    print("Access granted")\nelse:\n    print("Access denied")')
 + p('注意课件加的限定：这是权限规则的一个简化示例，不是完整的安全策略。真实系统还要考虑继承、角色、时间、审计等。')
 + cal('warn', '注意公式与代码的括号不同', '课件这一页的公式写作 <code>P ∨ Q ∧ R</code>，按优先级应读作 <code>P ∨ (Q ∧ R)</code>（管理员无条件通过，或有权限且公开）；而旁边那段代码写的是 <code>(is_admin or has_permission) and is_public</code>，对应 <code>(P ∨ Q) ∧ R</code>（管理员也要资源公开才行）。两者语义不同。答题时以题目给的括号为准：只给 <code>P ∨ Q ∧ R</code> 就按 AND 优先解释，写成带括号的形式再求值。')
 + h3('11.2 数字电路里的逻辑门')
 + p('数字电路用逻辑运算处理二进制信号：输入用 0/1 表示，逻辑门执行基本逻辑运算，多个门组合成更复杂的电路。')
 + tb(('逻辑门', '对应运算', '行为'),
      ('AND 门', '<code>P ∧ Q</code>', '两输入都为 1 才输出 1'),
      ('OR 门', '<code>P ∨ Q</code>', '任一输入为 1 就输出 1'),
      ('NOT 门', '<code>¬P</code>', '输入取反'),
      ('XOR 门', '<code>P ⊕ Q</code>', '两输入不同才输出 1'))
 + p('这四种门与本讲的四种运算符一一对应，而它们的真值表就是上面的表。第 5 章讲 AES 时提到「每轮都是逻辑运算」，指的就是这些门。第 2 讲的二进制加法器也是用 AND/OR/XOR 搭出来的。')
 + h3('11.3 数据库查询里的条件')
 + p('课件给了一个 SQL 例子：找出 GPA 高于 3.0 且学分高于 100 的学生：')
 + pre('SELECT *\nFROM Students\nWHERE GPA > 3.0 AND Credits > 100;')
 + p('并给了数据表：')
 + tb(('Student', 'GPA', 'Credits', '满足条件？'),
      ('Alice', '3.8', '120', '是'),
      ('Bob', '2.9', '90', '否（两项都不满足）'),
      ('Carol', '3.5', '110', '是'),
      ('David', '3.2', '80', '否（学分不够）'))
 + p('课件的连接句：<b>数据库筛选用逻辑条件识别满足要求的记录</b>。WHERE 子句里的 AND/OR/NOT 就是本讲的运算符，只是写成了英文关键字。')
 + h3('11.4 访问控制')
 + p('课件重新给了一组条件与规则：')
 + pre('A：用户是管理员\nP：用户有权限\nR：资源是公开的\n规则：A ∨ (P ∧ R)')
 + p('解释：满足以下任一即授予访问——① 用户是管理员；② 用户有权限<b>且</b>资源公开。')
 + tb(('情形', '结果'),
      ('管理员', '授予'),
      ('非管理员，有权限，资源公开', '授予'),
      ('非管理员，无权限', '拒绝'))
 + p('这张小表就是真值表的抽样：不必列全 8 行，只挑有代表性的情形。但考试若要求「完整真值表」，仍要列全 2^n 行。')
 + h3('11.5 AI 里的规则推理')
 + p('课件的例子是一个简单的推荐系统：')
 + pre('规则 1：若（考试分数高 且 完成全部作业）→ 推荐进阶课程\n规则 2：若（考试分数低 或 缺交多次作业）→ 推荐额外练习')
 + p('逻辑表达式：')
 + p('<b><code>(P ∧ Q) → R</code></b>　　<b><code>(S ∨ T) → U</code></b>')
 + p('其中 P 高分数、Q 完成作业、R 推荐进阶课、S 低分数、T 缺交、U 推荐练习。')
 + p('这种「条件 → 结论」的规则集合叫规则库，是早期专家系统的核心。现代系统用统计学习替代了大量手写规则，但可解释性场景（医疗、信贷）仍偏爱规则形式——因为每条决策都能回溯到某条规则。')
 + h2('十二、要点回顾')
 + p('课件最后收成五条：')
 + ol('<b>命题</b>：具有确定真值的陈述句',
      '<b>逻辑运算符</b>：NOT、AND、OR、XOR、蕴含、双条件',
      '<b>真值表</b>：展示所有真值组合',
      '<b>逻辑等价</b>：对所有组合取值都相同',
      '<b>计算应用</b>：编程、数据库、数字电路、访问控制、AI')
 + p('这五条正好对应本讲的五个板块，可以当复习提纲用。'))

_kw11 = K(('logic', '逻辑', 'The study of correct reasoning; rules for deciding whether a statement is true or false.'),
          ('proposition', '命题', 'A declarative statement with a definite truth value, true or false.'),
          ('truth value', '真值', 'True (T) or false (F).'),
          ('atomic proposition', '原子命题', 'A simple proposition that cannot be split further in the current representation.'),
          ('compound proposition', '复合命题', 'A proposition built from simpler ones using logical operators.'),
          ('negation', '否定', '<code>¬P</code>: if P is true then ¬P is false, and vice versa.'),
          ('conjunction', '合取', '<code>P ∧ Q</code>: true only when both are true.'),
          ('disjunction', '析取', '<code>P ∨ Q</code>: true when at least one is true.'),
          ('exclusive or', '异或', '<code>P ⊕ Q</code>: true when exactly one is true.'),
          ('implication', '蕴含', '<code>P → Q</code>: false only when P is true and Q is false.'),
          ('antecedent / consequent', '前件 / 后件', 'P is the antecedent, Q is the consequent of P → Q.'),
          ('biconditional', '双条件', '<code>P ↔ Q</code>: true when both have the same truth value.'),
          ('truth table', '真值表', 'Lists the value of an expression for every combination; 2^n rows for n propositions.'),
          ('operator precedence', '运算符优先级', 'NOT, then AND, then OR, then implication, then biconditional.'),
          ('logical equivalence', '逻辑等价', '<code>P ≡ Q</code>: same truth value for every combination.'),
          ('De Morgan laws', '德摩根律', '<code>¬(P ∧ Q) ≡ ¬P ∨ ¬Q</code> and <code>¬(P ∨ Q) ≡ ¬P ∧ ¬Q</code>.'))

_ex11 = (qa('例 1　判断下列语句是否为命题，并把后四句翻成逻辑表达式（P：计算机连上互联网；Q：系统正在运行；R：用户有管理员权限）：<br>① 计算机连上互联网了吗？② 系统正在运行。③ 请重启计算机。④ 10 大于 5。<br>(a) 计算机连上互联网且系统正在运行。(b) 用户有管理员权限或系统正在运行。(c) 计算机没有连上互联网。(d) 系统正在运行当且仅当计算机连上互联网。',
    p('<b>① 不是命题。</b>疑问句没有真值。')
    + p('<b>② 是命题。</b>陈述句，真值确定（按当时事实为真或假）。')
    + p('<b>③ 不是命题。</b>祈使句没有真值（它不描述世界，而是要求改变世界）。')
    + p('<b>④ 是命题。</b>陈述句，真值为真（10 &gt; 5 成立）。')
    + p('<b>(a)</b> 「且」→ 合取：<code>P ∧ Q</code>。')
    + p('<b>(b)</b> 「或」→ 析取：<code>R ∨ Q</code>（按给出的顺序是「管理员或系统运行」）。')
    + p('<b>(c)</b> 「没有」→ 否定：<code>¬P</code>。')
    + p('<b>(d)</b> 「当且仅当」→ 双条件：<code>Q ↔ P</code>（注意「系统正在运行」在前，所以 Q 写在左）。')
    + p('翻译的两个坑：① 词序决定左右，写反了虽等价（↔ 与 ∧ ∨ 都可交换）但在 → 的情况下会错；② 「没有」「不」这类否定词要认出来，别漏掉。'))
  + qa('例 2　某楼的门禁系统按 <code>(A ∧ S) ∨ E</code> 判断是否放行（A：授权员工；S：通过安全验证；E：楼门开放）。写出完整真值表，并列出所有放行的条件组合。',
    p('<b>第一步，三命题 → 8 行。</b>按 A、S、E 的位模式顺序列：')
    + tb(('A', 'S', 'E', 'A ∧ S', '结果 (A∧S) ∨ E'),
         ('T', 'T', 'T', 'T', 'T'),
         ('T', 'T', 'F', 'T', 'T'),
         ('T', 'F', 'T', 'F', 'T'),
         ('T', 'F', 'F', 'F', 'F'),
         ('F', 'T', 'T', 'F', 'T'),
         ('F', 'T', 'F', 'F', 'F'),
         ('F', 'F', 'T', 'F', 'T'),
         ('F', 'F', 'F', 'F', 'F'))
    + p('<b>第二步，读结果。</b>放行（T）的行是第 1、2、3、5、7 行，共 <b>5 种</b>组合。')
    + p('<b>第三步，用人话说清：</b>① 授权员工且通过验证（无论门开不开，E 无关）；② 门本来就是开放的（无论 A、S 如何）。')
    + p('<b>第四步，验证边界：</b>「非授权员工、未通过验证、门关着」→ 第 8 行 = F，拒绝。这个直觉检查能抓出列错行或算错列的错误。')
    + p('注意第 5、7 行：A 为假、S 为假也能放行，只因为 E 为真。这正是「支配律」的现实版——OR 的一边为真，另一边就不重要了。'))
  + qa('例 3　用等价律化简 <code>¬(P ∧ Q) ∨ (P ∧ Q)</code>，并说明用到了哪条律。',
    p('<b>第一步，认出结构。</b>设 <code>R = P ∧ Q</code>，原式就是 <code>¬R ∨ R</code>。')
    + p('<b>第二步，套用排中律。</b><code>¬R ∨ R ≡ T</code>（一个命题与它的否定取「或」，必然为真）。')
    + p('<b>第三步，结论：</b>原式恒为真，与 P、Q 的取值无关——它是一个<b>重言式</b>（tautology）。')
    + p('若不用等价律，也可以列 4 行真值表验证：P、Q 的每种组合下 <code>P ∧ Q</code> 与 <code>¬(P ∧ Q)</code> 恰有一个为真，故 OR 恒为真。两种方法结论一致。')
    + p('<b>迁移价值：</b>程序里 <code>if (x &gt; 0) or (not (x &gt; 0))</code> 这种写法恒为真，等于没写条件——这类「看起来在检查、实际没检查」的 bug，用等价律一眼就能发现。'))
  + qa('例 4　把 <code>P → Q</code> 用 ¬ 与 ∨ 改写，并用真值表验证；再说明这个改写为什么对电路设计有用。',
    p('<b>改写：</b><code>P → Q ≡ ¬P ∨ Q</code>。')
    + p('<b>验证表：</b>')
    + tb(('P', 'Q', 'P → Q', '¬P', '¬P ∨ Q'),
         ('T', 'T', 'T', 'F', 'T'),
         ('T', 'F', 'F', 'F', 'F'),
         ('F', 'T', 'T', 'T', 'T'),
         ('F', 'F', 'T', 'T', 'T'))
    + p('两列逐行相同，等价成立。特别注意 P 为假的两行：<code>¬P</code> 为 T，于是 <code>¬P ∨ Q</code> 必为 T——这就是「真空真」在算式上的体现。')
    + p('<b>为什么对电路有用：</b>蕴含不是一种基本门，硬件里没有「蕴含门」。把它化成 ¬ 与 ∨ 之后，只用 NOT 门与 OR 门（甚至只用 NAND 门）就能实现。这正是「用等价律把高层表达降到可实现的门级」的典型操作。')
    + p('延伸：同理 <code>P ↔ Q ≡ (P → Q) ∧ (Q → P) ≡ (¬P ∨ Q) ∧ (¬Q ∨ P)</code>，双条件也能消掉。')))

_pr11 = (ol('下列哪些是命题：① 明天会下雨吗？② 2 + 2 = 4。③ 请勿吸烟。④ x &gt; 3。⑤ 这座桥长 100 米。',
           '写出 <code>P ⊕ Q</code> 与 <code>P ↔ Q</code> 的真值表，并说出两者的差别。',
           '把 <code>¬(P ∨ Q)</code> 用德摩根律改写，并用真值表验证。',
           '某系统规则为 <code>(A ∨ B) ∧ C</code>，三命题，列真值表并指出为真的行。',
           '用等价律说明 <code>P → Q</code> 与 <code>¬Q → ¬P</code> 是否等价（逆否命题）。',
           '为什么「若 P 则 Q」在 P 为假时整体为真？用自己的话解释，并举一个生活例子。')
 + det('参考答案与思路',
    p('<b>1.</b> ② 是（真）；⑤ 是（真值确定，虽然需要测量）；① 不是（疑问句）；③ 不是（祈使句）；④ 不是（含自由变量 x，取值未定前无真值）。')
    + p('<b>2.</b> <code>P ⊕ Q</code>：T,T→F；T,F→T；F,T→T；F,F→F。<code>P ↔ Q</code>：T,T→T；T,F→F；F,T→F；F,F→T。差别只在「同真同假」两行：XOR 在两者相同时为 F、不同时为 T；双条件正好相反。所以 <code>P ↔ Q ≡ ¬(P ⊕ Q)</code>。')
    + p('<b>3.</b> <code>¬(P ∨ Q) ≡ ¬P ∧ ¬Q</code>。验证：P、Q 为 (T,T) 时左边 <code>¬T = F</code>，右边 <code>F ∧ F = F</code>；(T,F)：左 <code>¬T = F</code>，右 <code>F ∧ T = F</code>；(F,T)：左 F，右 <code>T ∧ F = F</code>；(F,F)：左 <code>¬F = T</code>，右 <code>T ∧ T = T</code>。四行全同。')
    + p('<b>4.</b> 变量是 A、B、C，共 8 行。<code>(A∨B)</code> 在 A 或 B 为真时为 T，再与 C 取合取，故只有在「C = T 且（A = T 或 B = T）」时为真：(T,T,T)、(T,F,T)、(F,T,T) 三行，其余五行全为 F（含 (T,T,F)、(F,F,T)）。')
    + p('<b>5.</b> 等价。<code>P → Q ≡ ¬P ∨ Q</code>；<code>¬Q → ¬P ≡ ¬(¬Q) ∨ ¬P ≡ Q ∨ ¬P</code>。两式只差 ∨ 的交换顺序，故等价。这叫逆否命题（contrapositive），与原命题同真假；而「逆命题」<code>Q → P</code> 与原命题<b>不</b>等价，这是最常见的推理错误。')
    + p('<b>6.</b> 因为蕴含只对「前件成立」的情形提出要求。生活例子：「如果明天下雨，我就带伞」——若明天没下雨，我无论带不带伞都不算违背承诺，所以这句话没有被证伪，逻辑上记为真。只有「下雨了却没带伞」才使这句话为假。')))

_exam11 = tb(('考点', '要点'),
    ('命题判定', '陈述句 + 确定真值；疑问、祈使、含自由变量的都不是'),
    ('六个运算符', '¬ ∧ ∨ ⊕ → ↔ 的语义与真值表'),
    ('OR vs XOR', '至少一个真 vs 恰好一个真；差别只在「两个都真」'),
    ('蕴含', '只有 T→F 为假；前件假时整体为真（真空真）'),
    ('真值表', '<code>2^n</code> 行；先列全组合，再逐列算中间结果'),
    ('优先级', '¬ > ∧ > ∨ > → > ↔；建议加括号'),
    ('等价律', '恒等、支配、双重否定、德摩根、交换、结合、分配、<code>P→Q ≡ ¬P∨Q</code>'),
    ('应用', '程序条件、逻辑门、SQL WHERE、访问控制、规则推理')) + (cal('exam', '必考', '必考：命题判定、六个运算符的真值表、蕴含的真空真、n 命题真值表行数与构造、英文句子与逻辑表达式的互译、德摩根律与分配律的化简、<code>P→Q ≡ ¬P∨Q</code>。')
 + cal('warn', '易错 1', '把 OR 当「二选一」。OR 在两真时也为真；要「恰好一个」必须用 XOR。')
 + cal('warn', '易错 2', '前件为假时把蕴含判为假。这是最高频的错误；记住「只有 T→F 才假」。')
 + cal('warn', '易错 3', '取反时不换运算符。<code>¬(P ∧ Q)</code> 不是 <code>¬P ∧ ¬Q</code>，而是 <code>¬P ∨ ¬Q</code>。')
 + cal('warn', '易错 4', '真值表漏行。三命题必须 8 行；建议按 000–111 的位模式顺序列，写完数一遍。')
 + cal('tip', '进阶', '① 逆否命题与原命题等价，逆命题不等价——这是逻辑推理题的核心区分；② 化简时优先用德摩根把否定「推到底」，再合并同类项；③ 电路里 NAND 门是「万能门」，任何表达式都能只用 NAND 实现；④ 程序里的短路求值（short-circuit）与逻辑等价无关，但会影响副作用顺序。'))

