      ('第 3 章 编码与压缩', 'Week 7', '怎么变小', 'RLE、Huffman、无损/有损'),
      ('第 4 章 存储与检索', 'Week 8', '放在哪、怎么组织', '存储层次、单位、文件格式、元数据'),
